def three_sum_multi(arr, target):
    MOD = 1_000_000_007
    n = len(arr)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if arr[i] + arr[j] + arr[k] == target:
                    count = (count + 1) % MOD
    return count

