public class Main {
    static int threeSumMulti(int[] arr, int target) {
        int MOD = 1_000_000_007;
        java.util.Arrays.sort(arr);
        int n = arr.length;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int j = i + 1, k = n - 1;
            int need = target - arr[i];
            while (j < k) {
                int s = arr[j] + arr[k];
                if (s < need) j++;
                else if (s > need) k--;
                else if (arr[j] != arr[k]) {
                    int leftVal = arr[j], rightVal = arr[k];
                    long leftCount = 1;
                    while (j + 1 < k && arr[j + 1] == leftVal) { leftCount++; j++; }
                    long rightCount = 1;
                    while (k - 1 > j && arr[k - 1] == rightVal) { rightCount++; k--; }
                    ans = (ans + leftCount * rightCount) % MOD;   // every left-value index with every right-value index
                    j++; k--;
                } else {
                    long count = k - j + 1;
                    ans = (ans + count * (count - 1) / 2) % MOD;  // one repeated value, count choose 2
                    break;
                }
            }
        }
        return (int) ans;
    }
}

